export const agendaItems: AgendaItem[] = [
  { day: "day-1", time: "08:00", title: "Registro y Café ☕ + Networking 🗣️", type: "break", room: "all", description: "¡Comencemos el día conectando con la comunidad!\n\nApartir de las 08:00 de la mañana abriremos las puertas para dar inicio a DevOpsDays Santiago 2026. Te invitamos a llegar con anticipación para realizar tu acreditación, retirar tu credencial y comenzar la experiencia sin apuros antes de las charlas del auditorio principal.\n\nMientras completas tu registro, podrás disfrutar del desayuno que hemos preparado especialmente para todos los asistentes y aprovechar este primer espacio para conocer a otros profesionales de la comunidad, intercambiar ideas y comenzar nuevas conversaciones.\n\nAdemás, nuestros patrocinadores ya estarán esperándote en sus stands con demostraciones, conocimiento, sorpresas y regalos exclusivos. Es el momento perfecto para descubrir nuevas tecnologías, conversar con expertos y sacar el máximo provecho desde el primer minuto del evento.\n\n¡Llega temprano, disfruta el desayuno y comienza a vivir la experiencia DevOpsDays junto a toda la comunidad!" },
  { day: "day-1", time: "08:45", title: "Apertura oficial 🎊", type: "ignite", room: "main", speakerIds: ["caio-mede", "karen-quijada", "sergio-canales", "jorge-valenzuela", "caco"], description: "¡La misión comienza!\n\nAcompáñanos en la bienvenida oficial de DevOpsDays Santiago 2026, donde el comité organizador dará inicio a dos días dedicados a compartir conocimiento, fortalecer la comunidad y explorar las tendencias que están transformando la industria tecnológica.\n\nConoce qué hemos preparado para esta edición y prepárate para una agenda llena de charlas, experiencias y conversaciones sobre DevOps, Inteligencia Artificial, Platform Engineering, Cloud Native y muchas otras prácticas que están definiendo el futuro del desarrollo y las operaciones.\n\nEs el momento de dar el puntapié inicial a una experiencia diseñada para aprender, conectar y volver a casa con nuevas ideas para impulsar tus próximos desafíos." },
  { day: "day-1", time: "09:00", id: "keynote-matias-sonnleitner", title: "DevOps ha muerto, larga vida al DevOps: de servir aplicaciones a servir modelos", type: "keynote", room: "main", speakerIds: ["matias-sonnleitner"], description: "Durante más de una década, DevOps nos enseñó a desplegar aplicaciones más rápido, más seguras y más resilientes. Pero la infraestructura que construimos para servir código ya no alcanza para servir inteligencia. Los modelos de IA no se despliegan, se entrenan, se versionan, se monitorean por drift y se sirven a escala — y eso exige una reconversión real, no solo un rebranding.\n\nEn este keynote exploraremos por qué el DevOps tradicional está llegando a su límite natural, qué se lleva consigo MLOps que no existía antes (datos, GPUs, pipelines de entrenamiento, observabilidad de modelos), y qué sobrevive intacto de la cultura DevOps que ya conocemos: colaboración, automatización y mejora continua.\n\nNo es el fin de una disciplina. Es su siguiente capítulo — y quienes lideran equipos de infraestructura hoy tienen la oportunidad de escribirlo.", topics: ["MLOps", "DevOps", "Inteligencia Artificial"] },
  { day: "day-1", time: "09:30", id: "panel-platinum", title: "Platinum - Trabajando con IA: Cómo cambiarán los equipos tecnológicos en los próximos 5 años", type: "panel", room: "main", speakerIds: ["diego-mondini", "francisco-merino", "leonardo-ramirez", "christian-onetto"], description: "La Inteligencia Artificial está transformando la forma en que trabajamos y colaboramos en los equipos tecnológicos. En este panel, exploraremos cómo la IA impactará en la estructura, roles y dinámicas de los equipos de desarrollo y operaciones en los próximos cinco años.\n\nNuestros expertos compartirán sus perspectivas sobre cómo la automatización, el aprendizaje automático y las herramientas impulsadas por IA cambiarán la manera en que abordamos los desafíos tecnológicos, mejorando la eficiencia, la toma de decisiones y la innovación.\n\nÚnete a nosotros para descubrir cómo prepararte para el futuro del trabajo en tecnología y cómo aprovechar al máximo las oportunidades que la IA ofrece a los equipos DevOps.", topics: ["Inteligencia Artificial", "Equipos Tecnológicos", "Transformación Digital"] },
  { day: "day-1", time: "10:30", title: "Coffee Break, Patrocinadores, y Comunidades 🚀", type: "break", room: "all", description: "¡Es momento de recargar energías y seguir haciendo comunidad!\n\nAprovecha este espacio para disfrutar de un café mientras recorres la plaza principal, donde nuestros patrocinadores y comunidades estarán esperándote para compartir experiencias, mostrar sus últimas novedades y conversar sobre tecnología, innovación y las oportunidades que están impulsando el ecosistema DevOps.\n\nVisita los stands, participa en las activaciones, descubre nuevas herramientas, llévate algunos regalos y conoce a las comunidades que hacen crecer el conocimiento abierto en nuestro país. Muchas de las mejores conversaciones del evento comienzan durante este break.\n\n¡Tómate un café, conecta con la comunidad y no dejes de explorar todo lo que nuestros patrocinadores y comunidades tienen preparado para ti!" },
  { id: "platinum-mondini", day: "day-1", time: "11:00", title: "Platinum: Desafíos y Mejores prácticas para el VibeOps/AgentOp", speakerIds: ["rudy-pinochet", "diego-mondini"], type: "talk", room: "main", description: "Una charla enfocada en cómo operar plataformas impulsadas por IA y agentes autónomos de forma segura, escalable y confiable. Exploraremos los principales desafíos de VibeOps/AgentOps, incluyendo observabilidad, gobernanza, seguridad, control de costos, evaluación de agentes, manejo de memoria y herramientas, además de las mejores prácticas para llevar soluciones basadas en agentes desde un prototipo hasta producción con resiliencia y confianza.", topics: ["Inteligencia Artificial", "Agentes", "DevOps"] },
  { day: "day-1", time: "11:30", title: "Conoce a nuestro Patrocinadores 🏆", host: "Mondini, Dynatrace, y TG Native", type: "ignite", room: "main", description: "Nuestros patrocinadores son una parte fundamental de DevOpsDays Santiago 2026, haciendo posible que este encuentro de la comunidad siga creciendo año a año.\n\nDurante esta sesión, algunas de las empresas que apoyan el evento tendrán la oportunidad de presentarse brevemente, compartir quiénes son, qué desafíos tecnológicos están resolviendo y cómo están contribuyendo al ecosistema DevOps, Cloud Native, Platform Engineering e Inteligencia Artificial.\n\nPresta atención a sus presentaciones, descubre nuevas tecnologías, oportunidades profesionales y no dudes en visitar sus stands durante los próximos breaks para continuar la conversación con sus equipos.\n\n¡Conoce a quienes hacen posible esta misión y están impulsando el futuro de la tecnología junto a nuestra comunidad!" },
  { id: "panel-organizadores", day: "day-1", time: "12:00", title: "Organizadores - Más allá de la IA: la evolución de las comunidades DevOps en LATAM en un mundo de IA", speakerIds: ["karen-quijada", "cami-punk", "axel-labruna", "caio-mede"], type: "panel", room: "main", durationSlots: 2, description: "La Inteligencia Artificial está transformando la forma en que desarrollamos software, operamos plataformas y compartimos conocimiento. Pero, ¿qué significa esta revolución para las comunidades DevOps de Latinoamérica?\n\nEn este panel reuniremos a organizadores de distintos DevOpsDays de la región para conversar sobre cómo la IA está cambiando la manera en que aprendemos, colaboramos y fortalecemos nuestras comunidades. Exploraremos los desafíos, oportunidades y el papel que seguirán desempeñando los encuentros presenciales, el conocimiento abierto y las redes de colaboración en un mundo donde la IA es cada vez más protagonista.\n\nUna conversación abierta para reflexionar sobre el presente y el futuro de nuestras comunidades, compartiendo experiencias, distintas perspectivas y una visión regional de hacia dónde evoluciona el movimiento DevOps en Latinoamérica.", topics: ["Inteligencia Artificial", "Equipos Tecnológicos", "Transformación Digital"] },
  { id: "alvaro-navarro", day: "day-1", time: "12:00", title: "El pod que tumbó la cadena: descubriendo fallas en cascada con Chaos Engineering en Kubernetes", speakerIds: ["alvaro-navarro"], type: "talk", room: "room-a", description: "La resiliencia no se asume, se prueba. En sistemas distribuidos de microservicios, las dependencias ocultas hacen que la falla de un componente aparentemente menor se propague en cascada hasta tumbar un flujo completo. La única forma de descubrir esos puntos frágiles antes que un incidente real es inyectar fallas a propósito: chaos engineering.\n\nEn esta charla comparto cómo llevamos el chaos engineering de un experimento manual a una práctica de plataforma usando Chaos Mesh sobre Kubernetes. La idea central: los experimentos de caos se declaran como YAML versionado y se ejecutan on-demand desde el pipeline, lo que abre la puerta a convertir la resiliencia en un gate obligatorio igual que los tests unitarios o el escaneo de seguridad antes de promover a producción. Voy a recorrer el catálogo de pruebas que se pueden automatizar, con ejemplos simplificados y reproducibles:\n\n  * PodChaos — matar pods (pod-kill, pod-failure, container-kill) para validar que el servicio se recupera solo.\n  * NetworkChaos — latencia, pérdida de paquetes, partición y corrupción para simular un backend caído o una red degradada.\n  * Pruebas a nivel de nodo — qué pasa cuando se pierde un nodo completo, no solo un pod.\n  * Schedules por cron — para simulacros recurrentes que ejercitan SLOs y el flujo de gestión de incidentes (game days).\n\nEl corazón de la charla es un caso real: durante un experimento descubrimos que apagar un solo pod hacía fallar toda la cadena de servicios aguas abajo. Ese hallazgo expuso dependencias que ningún diagrama mostraba y nos obligó a introducir circuit breakers y políticas de reintento donde no existían. La conclusión es que el chaos engineering no solo prueba resiliencia: revela la topología real de dependencias de tu arquitectura. Cierro con cómo evoluciona esto hacia una plataforma: del simulacro manual con runbook, al chaos on-demand en el pipeline.\n\nTe llevas: qué pruebas de caos puedes automatizar hoy, cómo declararlas en YAML y dispararlas desde el pipeline como gate de resiliencia, cómo usar el caos para descubrir dependencias ocultas y dónde te faltan circuit breakers, y los cuidados operativos (blast radius, rollback, horarios) para hacerlo sin romper producción.", topics: ["Chaos Engineering", "Kubernetes", "Resiliencia"]  },
  { id: "felipe-carvajal", day: "day-1", time: "12:00", title: "Tu LLM es un Nodo Bizantino: Patrones de Consenso para DevOps con IA", speakerIds: ["felipe-carvajal"], type: "talk", room: "room-b", description: "Ya desplegaste LLMs en el pipeline. Resumen incidentes, sugieren fixes de Terraform, generan runbooks, filtran ruido de alertas. Y la mayoría del tiempo están bien — hasta que están confidentemente, silenciosamente equivocados. El problema no es que los LLMs alucinan. El problema es que una alucinación es estructuralmente indistinguible de una respuesta correcta. El modelo no sabe que está mintiendo. Tu pipeline tampoco.Los sistemas distribuidos resolvieron un problema equivalente hace décadas: ¿cómo construyes un sistema confiable con nodos en los que no puedes confiar completamente? La respuesta fue la Tolerancia a Fallas Bizantinas — no confíes en ningún nodo individual, exige acuerdo entre caminos independientes antes de comprometerte con un resultado.Esa misma lógica se aplica directamente a los outputs de LLMs en un flujo DevOps. Una sola llamada al modelo es un nodo no confiable. Pasar esa misma consulta por un segundo modelo independiente — formulado de forma adversarial, no idéntica — es la verificación de consenso mínima viable. No es una bala de plata, pero cambia el modo de falla: de “respuesta incorrecta silenciosa“ a “desacuerdo que puedes detectar y enrutar“.\n\nEsta charla mapea ese framework a decisiones concretas que tomas hoy: cuándo una segunda llamada al modelo justifica la latencia, cómo estructurar un prompt de verificación para que realmente desafíe el primer output en lugar de simplemente confirmarlo, y dónde en un pipeline CI/CD tiene sentido agregar consenso versus dónde es overhead que no puedes pagar. Sin teoría de sistemas distribuidos. Una oración de BFT, el resto es arquitectura de pipelines.", topics: ["Inteligencia Artificial", "DevOps", "Automatización"] },
  { id: "gabriel-grobier", day: "day-1", time: "12:30", title: "Infraestructura Cognitiva: De Alertas a Investigación Autónoma con AWS y Agentes de IA", speakerIds: ["gabriel-grobier"], type: "talk", room: "room-a", description: "La operación moderna genera una enorme cantidad de alertas, pero la mayor parte del tiempo de un equipo DevOps o SRE no se invierte en recibirlas, sino en investigar qué ocurrió realmente.\n\nEn esta charla mostraré cómo construir una infraestructura cognitiva capaz de transformar eventos operacionales en investigaciones autónomas utilizando AWS, Amazon Bedrock, Python y Strands Agents.\n\nA través de una demostración práctica desplegada en entornos serverless, veremos cómo un agente puede recibir una alarma de CloudWatch, consultar métricas, revisar límites de servicio, analizar costos y correlacionar evidencia para generar hipótesis sobre la causa raíz de un incidente.\n\nExploraremos cómo Type Hinting y los Docstrings de Python se convierten en la interfaz que permite exponer capacidades operativas a modelos fundacionales sin necesidad de construir integraciones complejas.\n\nEl objetivo no es reemplazar a los equipos de operaciones, sino reducir drásticamente el tiempo de investigación y mostrar cómo evolucionar desde una operación reactiva basada en tickets hacia sistemas capaces de razonar sobre su propia infraestructura.", topics: ["Inteligencia Artificial", "DevOps", "Observabilidad"] },
  { id: "xavier-llauca", day: "day-1", time: "12:30", title: "Hardening Cloud-Native CI/CD: Applying OWASP’s Top 10 CI/CD Risks in Kubernetes", speakerIds: ["xavier-llauca"], type: "talk", room: "room-b", description: "En la era cloud-native, la velocidad de entrega es ley. Dependemos de pipelines de CI/CD para automatizar y desplegar software continuamente; sin embargo, esta automatización ha convertido a los pipelines en uno de los vectores de ataque más atractivos e impactantes dentro de la cadena de suministro de software (Software Supply Chain). Si el pipeline se compromete, todo el cluster está en riesgo.\n\nEsta charla aborda de manera directa el proyecto OWASP Top 10 CI/CD Security Risks, desmitificando las amenazas más críticas que acechan a la integración y entrega continua moderna: exposición de secretos, control de acceso deficiente, falta de validación en la integridad de artefactos y configuraciones inseguras. Pero no nos quedaremos solo en la teoría; llevaremos estos riesgos al terreno de juego real: Kubernetes.\n\n¿Qué aprenderás en esta sesión?\n\n  * Mapeo de Amenazas: Cómo se traducen los riesgos de OWASP en componentes vivos de un pipeline moderno y en workloads de Kubernetes.\n  * Walkthrough Técnico (Demo): Analizaremos un flujo comprometido para entender la anatomía de un ataque a la cadena de suministro.\n  * Mitigación Práctica: Implementación de controles reales mediante políticas de seguridad, validación de imágenes en tiempo de despliegue y aislamiento de cargas de trabajo dentro del ecosistema K8s.\n\nAl finalizar la sesión, los asistentes no solo entenderán los vectores de ataque más comunes, sino que se llevarán un marco estratégico y herramientas prácticas para evaluar, diagnosticar y fortalecer la seguridad de sus propios pipelines e infraestructura en producción.", topics: ["Seguridad", "DevOps", "Kubernetes"] },
  { day: "day-1", time: "13:00", title: "Almuerzo 🍽️ + Networking 🤝", type: "break", room: "all", description: "Es momento de hacer una pausa, recargar energías y seguir disfrutando de la experiencia DevOpsDays Santiago 2026.\n\nTodos los asistentes podrán retirar su almuerzo en el área de acreditación, mientras que los asistentes con entrada VIP podrán hacerlo cómodamente en el sector VIP habilitado especialmente para ellos.\n\nEste espacio ha sido pensado para que disfrutes tu almuerzo con tranquilidad y, al mismo tiempo, continúes conectando con la comunidad. Aprovecha para conversar con otros asistentes, intercambiar experiencias y recorrer la plaza principal, donde nuestros patrocinadores y comunidades seguirán esperándote con demostraciones, novedades, actividades y regalos.\n\n¡Buen provecho! Disfruta este momento para crear nuevas conexiones y sacar el máximo provecho de todo lo que el evento tiene preparado para ti." },
  { id: "cesar-lorca", day: "day-1", time: "14:30", title: "De ClickOps a GitOps: Cómo operar IA Privada en Producción con SUSE AI Factory y SUSE Rancher", speakerIds: ["cesar-lorca"], type: "talk", room: "main", description: "La IA empresarial ya no se trata solo de entrenar modelos, sino de operarlos con disciplina DevOps. En esta charla veremos cómo SUSE AI Factory y SUSE AI Factory with NVIDIA, sobre SUSE Rancher, permiten pasar de implementaciones manuales y fragmentadas a una operación declarativa, repetible y gobernada con GitOps, Blueprints validados y control de plataforma. El foco estará en cómo reducir fricción operativa, acelerar despliegues y mantener consistencia entre equipos y ambientes.", topics: ["Inteligencia Artificial", "DevOps", "GitOps"] },
  { id: "cami-punk", day: "day-1", time: "14:30", title: "Supercharging DevOps with Google Antigravity and Claude AI", speakerIds: ["cami-punk"], type: "talk", room: "room-a", description: "Descubre el potencial de Google Antigravity, un entorno de desarrollo integrado (IDE) avanzado y basado en agentes, diseñado para transformar la forma en que desarrollas software, trabajando con Claude AI en tareas de DevOps. En esta sesión, exploraremos casos de uso reales y demostraremos cómo Antigravity, junto con Claude AI, puede automatizar de forma autónoma tareas de «Infrastructure as Code» (IaC), crear infraestructura, resolver problemas, revisar solicitudes de incorporación de cambios (PR) y ayudarnos en nuestro día a día. Aprende a sacar el máximo partido a tu trabajo y a dejar que la IA se encargue de las tareas más pesadas en tu proceso de DevOps.", topics: ["Inteligencia Artificial", "DevOps", "Automatización"] },
  { id: "alonso-utreras", day: "day-1", time: "15:00", title: "Un caso real con Wide Events: Cómo mejoramos nuestra observabilidad y detectamos problemas en tiempo real", speakerIds: ["alonso-utreras"], type: "talk", room: "room-a", description: "Se muestra un caso real en Claro, en el sistema de IVR (Interactive Voice Response) lo que responde cuando se llama al 103, ofreciendo distintos números. Nuestros servicios en AWS se conectan con servicios On Premise que a veces se caían. Cuando ocurrían estas caídas, debíamos analizar los logs de forma extensa para encontrar problemas y aplicar soluciones. Se definió un sistema de logs siguiendo la lógica de canonical log lines, logs unitarios que contuvieran información respecto a todo el procesamiento de un request en una sola línea.\n\nEsto nos permitió generar monitoreos de todos nuestros servicios de manera unificada, reduciendo el tiempo que demorábamos en encontrar problemas. Esta ventaja se tradujo inmediatamente en ganancias para el negocio (menos tiempo caído implica menos pérdidas) y más  tiempo dedicado a desarrollos en vez de resolver problemas en producción.", topics: ["Observabilidad", "Monitoreo", "Detección de Problemas"] },
  { id: "carlos-estay", day: "day-1", time: "14:30", title: "Semantic Routing: El Corazón Inteligente de los Agentes", speakerIds: ["carlos-estay"], type: "workshop", room: "room-b", durationSlots: 2, description: "En este taller práctico, exploraremos cómo construir un sistema de enrutamiento semántico para agentes de IA, que permita a los agentes comprender y procesar información de manera más eficiente y efectiva. Aprenderemos a diseñar arquitecturas que faciliten la comunicación entre agentes, optimizando la toma de decisiones y mejorando la capacidad de respuesta ante diferentes escenarios.\n\nA través de ejercicios prácticos, los participantes tendrán la oportunidad de implementar un sistema de enrutamiento semántico utilizando herramientas y frameworks modernos, aplicando conceptos de procesamiento del lenguaje natural (NLP) y aprendizaje automático para mejorar la interacción entre agentes y usuarios.\n\nAl finalizar el taller, los asistentes estarán equipados con conocimientos y habilidades para desarrollar sistemas de agentes más inteligentes y adaptativos, capaces de manejar tareas complejas y colaborar de manera más efectiva en entornos dinámicos.", topics: ["Inteligencia Artificial", "Agentes", "Procesamiento del Lenguaje Natural"] },
  { id: "german-blanch", day: "day-1", time: "15:00", title: "Cuando la “fábrica del software” se vuelve el objetivo", speakerIds: ["german-blanch"], type: "talk", room: "main", description: "Los pipelines y automatizaciones modernas concentran cada vez más permisos, decisiones y confianza. Cuando algo falla ahí, el impacto se propaga rápido. En esta charla analizaremos por qué la cadena de entrega del software se transformó en un nuevo vector de ataque y qué prácticas de seguridad ayudan a reducir riesgos sin convertir la seguridad en un freno operativo.", topics: ["Seguridad", "DevOps", "Automatización"] },
  { id: "francisco-merino", day: "day-1", time: "15:30", title: "Platinum: De DevOps a AutonomousOps: Cómo la IA y la Observabilidad están redefiniendo las operaciones digitales", speakerIds: ["francisco-merino"], type: "talk", room: "main", description: "Esta charla explora cómo la Observabilidad está evolucionando de la simple recolección de métricas, logs y trazas hacia sistemas capaces de identificar la causa raíz real detrás de un incidente, no solo su correlación. Veremos cómo la IA basada en contexto aplicada a estos datos está cambiando la forma en que los equipos DevOps detectan, entienden y responden a problemas en sistemas distribuidos, reduciendo el ruido y acelerando el diagnóstico. Una mirada técnica sobre el estado actual de la IA en Observabilidad, y hacia dónde va la disciplina.", topics: ["Inteligencia Artificial", "Observabilidad", "DevOps"] },
  { day: "day-1", time: "16:00", title: "Cierre Día 1 + Anuncios + Llamado a Networking", host: "Comité Organizador", speakerIds: ["caio-mede", "karen-quijada", "sergio-canales", "jorge-valenzuela", "caco"], type: "ignite", room: "main", description: "¡Así concluimos un increíble primer día de DevOpsDays Santiago 2026!\n\nAcompáñanos en el cierre de la jornada mientras repasamos los momentos más destacados del día, compartimos anuncios importantes y te contamos todo lo que hemos preparado para la segunda jornada del evento.\n\nAunque las charlas llegan a su fin por hoy, la experiencia continúa. Te invitamos a aprovechar los últimos minutos para seguir recorriendo la plaza principal, visitar a nuestros patrocinadores, conversar con los speakers y fortalecer esas conexiones que hacen única a nuestra comunidad.\n\nY recuerda: esto aún no termina. Mañana nos espera un nuevo día lleno de conocimiento, experiencias, nuevas charlas, workshops y muchas oportunidades para aprender, compartir y seguir celebrando la gran fiesta del DevOps en Chile.\n\n¡Nos vemos mañana para continuar esta misión junto a toda la comunidad! 🚀" },
  { day: "day-2", time: "08:00", title: "Registro y Café ☕ + Networking 🗣️", type: "break", room: "all", description: "¡Bienvenidos al segundo día de DevOpsDays Santiago 2026!\n\nSi ya asististe a la primera jornada, solo necesitas presentar tu credencial para ingresar y retirar tu desayuno. Si vienes por primera vez, nuestro equipo de acreditación estará listo para ayudarte con tu registro y entregarte todo lo necesario para comenzar la experiencia.\n\nAntes del inicio de las charlas, aprovecha este espacio para disfrutar del desayuno, recorrer la plaza principal y visitar a nuestros patrocinadores y comunidades. Es una excelente oportunidad para conocer las últimas novedades, participar en las activaciones, conversar con expertos y reencontrarte con las personas que conociste durante el primer día.\n\n¡Comienza la segunda jornada con energía, fortalece tus conexiones y prepárate para otro día lleno de conocimiento, innovación y comunidad!" },
  { day: "day-2", time: "08:45", title: "Apertura oficial 🎊", type: "ignite", room: "main", speakerIds: ["caio-mede", "karen-quijada", "sergio-canales", "jorge-valenzuela", "caco"], description: "¡Comienza una nueva jornada de aprendizaje, inspiración y comunidad!\n\nTe damos la bienvenida al segundo día de DevOpsDays Santiago 2026. Si ayer fue solo el comienzo, hoy continuaremos explorando las ideas, tecnologías y experiencias que están transformando la forma en que construimos y operamos software.\n\nEl comité organizador dará inicio a esta segunda jornada con algunos anuncios y una mirada a todo lo que nos espera durante el día: nuevas charlas, workshops, conversaciones y muchas oportunidades para seguir aprendiendo sobre DevOps, Inteligencia Artificial, Platform Engineering, Cloud Native y las prácticas que están marcando el futuro de nuestra industria.\n\nPrepárate para seguir compartiendo conocimiento, fortaleciendo tu red de contactos y viviendo el espíritu de colaboración que hace único a DevOpsDays.\n\n¡Que comience el segundo día de esta gran fiesta de la comunidad DevOps en Chile! 🚀" },
  { id: "keynote-andres-barrientos", day: "day-2", time: "09:00", title: "Evolucion de DevOps a DevSecOps, IA como empuje de coversion laboral", speakerIds: ["andres-barrientos"], type: "keynote", room: "main", description: "En esta keynote, exploraremos la evolución de DevOps hacia DevSecOps y cómo la Inteligencia Artificial está impulsando cambios significativos en el panorama laboral. Analizaremos cómo la integración de prácticas de seguridad en el ciclo de vida del desarrollo de software ha transformado la forma en que los equipos operan, y cómo la IA está acelerando esta transición.\n\nDiscutiremos las oportunidades y desafíos que surgen al adoptar DevSecOps, incluyendo la automatización de pruebas de seguridad, la gestión de vulnerabilidades y la implementación de políticas de seguridad en entornos ágiles. Además, examinaremos cómo la IA está facilitando la detección proactiva de amenazas y mejorando la eficiencia operativa.\n\nLos asistentes obtendrán una comprensión profunda de cómo estas tendencias están moldeando el futuro del trabajo en tecnología, y cómo pueden prepararse para aprovechar las oportunidades que surgen en este nuevo paradigma.", topics: ["DevSecOps", "Inteligencia Artificial", "Transformación Laboral"] },
  { day: "day-2", time: "09:30", title: "Platinum: TG Corp", host: "Por confirmar", type: "talk", room: "main" },
  { day: "day-2", time: "10:00", title: "Coffee Break, Patrocinadores, y Comunidades 🚀", type: "break", room: "all", description: "¡Es momento de recargar energías y seguir haciendo comunidad!\n\nAprovecha este espacio para disfrutar de un café mientras recorres la plaza principal, donde nuestros patrocinadores y comunidades estarán esperándote para compartir experiencias, mostrar sus últimas novedades y conversar sobre tecnología, innovación y las oportunidades que están impulsando el ecosistema DevOps.\n\nVisita los stands, participa en las activaciones, descubre nuevas herramientas, llévate algunos regalos y conoce a las comunidades que hacen crecer el conocimiento abierto en nuestro país. Muchas de las mejores conversaciones del evento comienzan durante este break.\n\n¡Tómate un café, conecta con la comunidad y no dejes de explorar todo lo que nuestros patrocinadores y comunidades tienen preparado para ti!" },
  { id: "keynote-johan-prieto", day: "day-2", time: "10:30", title: "El idioma también es infraestructura: preparar a Latinoamérica para la próxima ola tecnológica", speakerIds: ["johan-prieto"], type: "keynote", room: "main", description: "Latinoamérica está viviendo un momento decisivo. Las empresas internacionales miran cada vez más a la región como un foco de talento tecnológico, impulsadas por su crecimiento digital, su cercanía cultural y su capacidad para construir software, operar plataformas y participar en ecosistemas globales.\n\nPero existe una brecha silenciosa que todavía limita ese potencial: el idioma.\n\nDevOps, Kubernetes, Platform Engineering y muchas de las prácticas modernas de tecnología siguen aprendidas, documentadas y discutidas principalmente en inglés. Para miles de personas, esto no representa solo una dificultad técnica; también genera miedo, inseguridad y la sensación de estar entrando solas a un mundo que parece diseñado en otro idioma.\n\nEsta charla nace desde esa realidad. Desde quienes alguna vez comenzaron leyendo documentación sin entenderlo todo. Desde quienes sintieron que la tecnología era más difícil no por falta de capacidad, sino por falta de acceso. Y desde quienes encontraron en las comunidades una forma de respaldo, acompañamiento y crecimiento.\n\nLa propuesta es simple, pero poderosa: el idioma también es infraestructura.\n\nConstruir conocimiento técnico en español no es solo traducir. Es unir, conectar y abrir caminos. Es fortalecer comunidades, acelerar el aprendizaje y preparar a más personas para participar en la próxima ola tecnológica de Latinoamérica.\n\nLa audiencia se llevará una reflexión clara: si queremos que la región crezca como potencia tecnológica, necesitamos más que herramientas. Necesitamos conocimiento accesible, comunidades activas y una tecnología que también hable nuestro idioma.", topics: ["Comunidades", "Educación Tecnológica", "Acceso al Conocimiento"] },
  { day: "day-2", time: "11:00", title: "Conoce a nuestro Patrocinadores 🏆", host: "Axmos + Datadog, Red Hat, Technology Solutions, y Manage Engine", type: "ignite", room: "main", description: "Nuestros patrocinadores son una parte fundamental de DevOpsDays Santiago 2026, haciendo posible que este encuentro de la comunidad siga creciendo año a año.\n\nDurante esta sesión, algunas de las empresas que apoyan el evento tendrán la oportunidad de presentarse brevemente, compartir quiénes son, qué desafíos tecnológicos están resolviendo y cómo están contribuyendo al ecosistema DevOps, Cloud Native, Platform Engineering e Inteligencia Artificial.\n\nPresta atención a sus presentaciones, descubre nuevas tecnologías, oportunidades profesionales y no dudes en visitar sus stands durante los próximos breaks para continuar la conversación con sus equipos.\n\n¡Conoce a quienes hacen posible esta misión y están impulsando el futuro de la tecnología junto a nuestra comunidad!" },
  { id: "melisa-arenas", day: "day-2", time: "11:30", title: "Platinum: Jarvis bot Always on-Call", speakerIds: ["melisa-arenas"], type: "talk", room: "main", description: "En el equipo de Site Reliability Engineering (SRE), la disponibilidad, la reducción del toil (trabajo repetitivo) y la minimización del Mean Time to Resolution (MTTR) son prioridades críticas. En esta conferencia, presentaremos el diseño e impacto de Jarvis Bot, nuestro First Responder automatizado integrado en Jira Service Management para mantener la resiliencia operativa de nuestros sistemas 24/7.\n\nDurante la sesión, compartiremos cómo desde SRE estructuramos este bot para escalar nuestras operaciones mediante tres pilares:\n\n  * Triaje y enriquecimiento dinámico: Automatización del análisis inicial y de la recolección de contexto con el usuario, eliminando el trabajo manual en las primeras fases del incidente.\n  * Troubleshooting estandarizado: Ejecución de guías de diagnóstico automatizadas para los ingenieros de guardia (on-call), alineadas con los runbooks oficiales del equipo.\n  * Asistencia conversacional y gestión del conocimiento: Soporte en tiempo real para la resolución de dudas técnicas complejas, cruzando la documentación de Google Cloud con el historial de incidentes para acelerar la curva de aprendizaje del equipo.\n\nUna visión práctica de cómo aplicamos cultura y principios SRE para automatizar la respuesta a incidentes, proteger el tiempo de nuestros ingenieros y garantizar una operación verdaderamente “always on”.", topics: ["Site Reliability Engineering", "Automatización", "Inteligencia Artificial"]  },
  { id: "axel-labruna", day: "day-2", time: "12:00", title: "AgentOps: el futuro que ya llegó", speakerIds: ["axel-labruna"], type: "talk", room: "main", description: "¿Y si el próximo salto de eficiencia en DevSecOps no viniera de más herramientas, sino de agentes capaces de razonar, coordinarse y ejecutar por nosotros?\n\nLa inteligencia artificial agéntica dejó de ser una promesa futurista: ya está cambiando la forma en que diseñamos, automatizamos y escalamos flujos de ingeniería. En esta charla exploraremos cómo AgentOps permite llevar los agentes de IA desde una demo interesante hasta arquitecturas reales, gobernables y orientadas a impacto.\n\nPresentaremos arquitecturas agénticas aplicadas a escenarios de DevSecOps, mostrando cómo diseñar agentes con responsabilidades claras, contratos explícitos, trazabilidad y mecanismos de colaboración. También revisaremos patrones de diseño para construir soluciones más robustas, reutilizables y seguras.\n\nA través de ejemplos prácticos y demos basadas en desarrollos reales, veremos cómo estos enfoques pueden acelerar actividades como análisis, generación de artefactos, validaciones, revisión de código, documentación, seguridad y automatización de pipelines, reduciendo esfuerzo operativo, tiempos de entrega y costos.\n\nLa audiencia se llevará una visión concreta de qué es AgentOps, cómo empezar a diseñar arquitecturas agénticas útiles, qué patrones aplicar y cómo convertir esta tendencia en una ventaja real para equipos de tecnología, producto y negocio.", topics: ["Inteligencia Artificial", "DevOps", "Automatización"] },
  { id: "andre-fellipe", day: "day-2", time: "12:00", title: "De la nube a la tierra: Extendiendo un flujo de trabajo GitOps de la nube a Kubernetes on-premises", speakerIds: ["andre-fellipe"], type: "talk", room: "room-a", description: "¿Qué sucede cuando a una empresa fuertemente regulada le encanta la agilidad de su flujo de trabajo GitOps en la nube pública, pero choca con un muro al intentar replicar esa misma experiencia en sus centros de datos on-premises? Frecuentemente, la adopción de prácticas DevOps modernas se estanca debido a la fricción de la infraestructura física y los estrictos controles locales, creando flujos de trabajo fragmentados entre los equipos de desarrollo y operaciones.\n\nEn esta sesión, exploraremos cómo romper este silo extendiendo una arquitectura GitOps madura directamente hacia clústeres Kubernetes bare-metal.\n\nAbordaremos este desafío desde la perspectiva del Platform Engineering: cómo abstraer por completo la compleja capa de infraestructura subyacente. Demostraremos cómo permitir a los desarrolladores desplegar aplicaciones on-premises con la misma “fricción cero“ que esperan de un entorno cloud. Al mismo tiempo, mostraremos cómo el equipo de plataforma puede utilizar Rancher y el ecosistema open source para gestionar el trabajo pesado de la orquestación a nivel local.\n\nLos asistentes se llevarán una guía arquitectónica práctica y aplicable para construir una plataforma híbrida verdaderamente unificada. Aprenderemos a estandarizar la postura de seguridad, el control de accesos y la aplicación de políticas a través del puente nube-tierra, logrando el equilibrio perfecto entre el rigor operativo corporativo y la agilidad de los desarrolladores.", topics: ["GitOps", "Kubernetes", "Platform Engineering"] },
  { id: "taller-redhat", day: "day-2", time: "12:00", title: "De Semanas a Minutos: Blindando tu Software Supply Chain con Red Hat Advanced Developer Suite", speakerIds: ["francisco-meneses", "francisco-raposo"], type: "workshop", room: "room-b", durationSlots: 2, description: "¿Es posible acelerar la entrega de software sin sacrificar un ápice de seguridad? La respuesta es sí. Red Hat Advanced Developer Suite (RHADS) redefine la experiencia del desarrollador al fusionar una alta productividad con la automatización nativa de la seguridad y el cumplimiento (compliance).\n\nEn esta sesión ultra práctica, romperemos el mito de que la seguridad ralentiza el pipeline. Mostraremos cómo implementar automatización de CI/CD de nivel empresarial utilizando dos de los caminos más potentes del ecosistema: Tekton y Jenkins. Descubrirás cómo las organizaciones líderes están reduciendo la configuración de nuevos proyectos de semanas a solo minutos, alcanzando un 100% de cumplimiento automatizado en su cadena de suministro de software.\n\nComo bonus, realizaremos la instalación en vivo de RHADS utilizando la CLI de Red Hat Trusted Software Supply Chain (tssc-cli), revelando los secretos técnicos para desplegar esta arquitectura sin fricciones.\n\nIdeal para: Ingenieros DevOps, Arquitectos de Software, Tech Leads y apasionados de DevSecOps que buscan automatizar la seguridad desde la primera línea de código.¿Qué veremos en esta sesión? (Agenda del Demo)\n\n  * El Big Picture: Contexto técnico, resultados de negocio y respuestas a los dolores de cabeza más comunes en la cadena de suministro.\n  * Bajo el Capó: Requerimientos técnicos, arquitectura, gestión de credenciales y troubleshooting en directo.\n  * RHADS en Acción con Tekton:\n   Construcción: Creación segura de la aplicación.\n   Promoción: Paso inteligente y verificado del artefacto hacia el entorno de Stage.\n   Liberación: Despliegue continuo y 100% confiable en Producción (Prod).", topics: ["Seguridad", "DevSecOps", "Automatización"] },
  { id: "luis-segura", day: "day-2", time: "12:30", title: "DevSecOps e IA, como encaja todo en el SDLC", speakerIds: ["luis-segura"], type: "talk", room: "room-a", description: "Desde Prima AFP, empresa que forma parte de Credicorp, el grupo financiero más grande del Perú, tenemos el agrado de presentar nuestra iniciativa orientada a la creación e incorporación de agentes inteligentes dentro del ciclo de vida de desarrollo de software (SDLC), con el objetivo de acelerar la salida de releases, optimizar procesos y fortalecer la entrega continua de valor al negocio.\n\nEn esta ponencia compartiremos cómo la implementación de agentes en distintas etapas del SDLC viene permitiendo mejorar la eficiencia en actividades clave como el desarrollo, validación, aseguramiento de calidad, controles de seguridad y despliegue, contribuyendo a una operación más ágil, estandarizada y confiable.\n\nFinalmente, abordaremos esta iniciativa desde una perspectiva DevSecOps, resaltando la importancia de integrar la seguridad, la automatización y la gobernanza desde las primeras etapas del desarrollo, para lograr releases más rápidos, seguros y alineados con las necesidades del negocio y de nuestros clientes.", topics: ["DevSecOps", "Inteligencia Artificial", "Ciclo de Vida de Desarrollo de Software"] },
  { id: "boris-quiroz", day: "day-2", time: "12:30", title: "Los agentes necesitan plata: x402 como infraestructura para la web3", speakerIds: ["boris-quiroz"], type: "talk", room: "main", description: "La próxima ola de usuarios de internet no será humana, sino que será software autónomo. Los famosos agentes de inteligencia artificial ya son capaces de descubrir herramientas, evaluar opciones, ejecutar tareas y tomar decisiones en tiempo real. Pero para operar de verdad en la web abierta, a estos agentes todavía les falta una capacidad fundamental: pagar.\n\nHoy internet tiene estándares maduros para conectar sistemas, y realizar procesos de autenticación y autorizacin, pero los pagos siguen viviendo fuera del flujo natural. Suscripciones, dashboards, tarjetas, contratos manuales y APIs cerradas introducen fricción en un mundo donde los consumidores ya no serán personas haciendo clic, sino agentes tomando decisiones automáticas, en nanosegundos.\n\nEn esta charla exploraré x402 como una pieza de infraestructura para esa nueva realidad: una forma de integrar pagos programáticos en el ciclo normal de consumo de servicios y APIs. A partir de conceptos como L402 y su evolución hacia escenarios machine-to-machine, veremos cómo una API puede expresar precio, cómo un agente puede pagar por acceso sin intervención humana y qué nuevas arquitecturas se habilitan cuando el pago se vuelve una capacidad nativa del protocolo.\n\nMás que una charla sobre monetización, esta es una charla sobre diseño de plataformas para una nueva clase de clientes. Si estamos construyendo una web donde los agentes actuarán como participantes de primera clase, entonces necesitamos infraestructura que les permita no solo autenticarse y ejecutar acciones, sino también intercambiar valor. En otras palabras: si los agentes van a trabajar en internet, necesitan plata.", topics: ["Agentes", "Web3", "Infraestructura"] },
  { day: "day-2", time: "13:00", title: "Almuerzo 🍽️ + Networking 🤝", type: "break", room: "all", description: "Es momento de hacer una pausa, recargar energías y seguir disfrutando de la experiencia DevOpsDays Santiago 2026.\n\nTodos los asistentes podrán retirar su almuerzo en el área de acreditación, mientras que los asistentes con entrada VIP podrán hacerlo cómodamente en el sector VIP habilitado especialmente para ellos.\n\nEste espacio ha sido pensado para que disfrutes tu almuerzo con tranquilidad y, al mismo tiempo, continúes conectando con la comunidad. Aprovecha para conversar con otros asistentes, intercambiar experiencias y recorrer la plaza principal, donde nuestros patrocinadores y comunidades seguirán esperándote con demostraciones, novedades, actividades y regalos.\n\n¡Buen provecho! Disfruta este momento para crear nuevas conexiones y sacar el máximo provecho de todo lo que el evento tiene preparado para ti." },
  { id: "meraioth-ulloa", day: "day-2", time: "14:30", title: "Movimiento de tenants en sharding lógico", speakerIds: ["meraioth-ulloa"], type: "talk", room: "main", description: "En aplicaciones SaaS multi-tenant de alta concurrencia, distribuir la carga operativa equitativamente entre shards es crítico para evitar alertas de saturación y agotamiento de memoria, un problema que heurísticas estáticas basadas en cantidad de usuarios no logran anticipar correctamente. Este trabajo detalla la implementación de un sistema de observabilidad para Buk que, ante las restricciones de extensiones en Amazon RDS, propaga la identidad del inquilino usando spans de OTEL para aislar y medir el uso transaccional real por esquema. Esta telemetría alimenta una métrica compuesta que pondera el uso de CPU, I/O y escrituras, generando un ranking ordinal accionable del impacto en la infraestructura. Lo que sigue es preparar al sistema y la infraestructura para que mover un inquilino no sea costoso en términos de disponibilidad de la plataforma antes de actuar en base a las recomendaciones otorgadas.", topics: ["Observabilidad", "Sharding", "Multi-Tenant"] },
  { day: "day-2", time: "14:30", title: "Pendiente", host: "Por confirmar", type: "talk", room: "room-a" },
  { id: "josua-castro", day: "day-2", time: "14:30", title: "Zero Trust en Kubernetes: seguridad para microservicios Java con Mutual TLS", speakerIds: ["josua-castro"], type: "talk", room: "room-b", description: "La comunicación entre servicios suele ser uno de los puntos más críticos en términos de seguridad. Muchas aplicaciones aún confían en redes internas o configuraciones básicas que no garantizan la identidad real de los servicios que se comunican entre sí.\n\nEn esta charla exploraremos cómo aplicar el modelo Zero Trust en Kubernetes para proteger microservicios Java mediante Mutual TLS (mTLS). Veremos cómo los servicios pueden autenticarse mutuamente, cifrar su comunicación y garantizar que solo los servicios autorizados puedan interactuar entre sí. A través de ejemplos prácticos, mostraremos cómo implementar esta estrategia para fortalecer la seguridad en arquitecturas cloud-native, reduciendo riesgos y mejorando la confianza entre componentes distribuidos. El objetivo es que los equipos puedan construir aplicaciones modernas con comunicación segura, identidad verificable y protección end-to-end entre servicios.", topics: ["Seguridad", "Kubernetes", "Zero Trust"] },
  { id: "avattar", day: "day-2", time: "15:00", title: "Acelerando el ciclo de vida del software con Agentes Inteligentes", speakerIds: ["jessica-grenier", "carlos-gattoni"], type: "talk", room: "main", description: "Descubre cómo los agentes de IA están transformando el desarrollo y aseguramiento de calidad del software. En esta charla revisaremos casos reales de aplicación en todo el ciclo de vida, desde el análisis de requerimientos hasta producción, mostrando cómo utilizar IA para automatizar tareas, reducir tiempos, mejorar la calidad y aumentar la productividad de los equipos.", topics: ["Inteligencia Artificial", "Automatización", "Ciclo de Vida del Software"] },
  { id: "pilar-rebolledo", day: "day-2", time: "15:00", title: "De la intuición a la precisión: diseño de planes de prueba con IA y automatización de ejecución con PARASOFT", speakerIds: ["pilar-rebolledo"], type: "talk", room: "room-a", description: "El diseño de planes de prueba funcionales sigue siendo, en muchos equipos, un proceso basado en la intuición del tester: dependiente de la experiencia individual, difícil de escalar y con cobertura inconsistente. Esta charla presenta una implementación real que cambia ese paradigma.\n\nCombinamos inteligencia artificial para analizar requerimientos y generar planes de prueba estructurados, con cobertura basada en criterios objetivos, y PARASOFT como motor de automatización para la ejecución de pruebas funcionales dentro del pipeline CI/CD. El resultado: un ciclo de testing más predecible, trazable y eficiente.\n\nA lo largo de la charla abordaremos la arquitectura de la solución, cómo se integra IA en la fase de diseño, cómo PARASOFT gestiona la ejecución automatizada, las métricas obtenidas y las lecciones aprendidas en un entorno real. Una charla para equipos de QA, desarrolladores y líderes técnicos que quieren evolucionar su estrategia de testing dentro de una cultura DevOps.", topics: ["Testing", "Inteligencia Artificial", "Automatización"] },
  { id: "francisco-meneses", day: "day-2", time: "15:00", title: "Tu agente de IA no va a escalar (y aquí tienes cómo arreglarlo)", speakerIds: ["francisco-meneses"], type: "talk", room: "room-b", description: "Crear agentes de IA es fácil. Escalarlos, mantenerlos y operarlos en el tiempo es el verdadero desafío.\n\nEn esta charla veremos cómo pasar de prompts y asistentes aislados a sistemas de agentes basados en skills, subagentes y workflows, mostrando en vivo cómo evolucionar una solución y medir su impacto en tiempo, calidad y costo.\n\nAdemás, exploraremos el día 2 de la IA: cómo hacer que estas prácticas sean sostenibles y escalables dentro de una organización.", topics: ["Inteligencia Artificial", "Agentes", "Escalabilidad"] },
  { id: "keynote-fabrizio-sgura", day: "day-2", time: "15:30", title: "The AI-Native Engineer", speakerIds: ["fabrizio-sgura"], type: "keynote", room: "main", description: "Durante años, la fórmula para mantenerse relevante fue relativamente simple: aprender la siguiente tecnología antes que los demás.\n\nLinux, cloud, Kubernetes, observabilidad, GitOps, Platform Engineering. Cada nueva ola tecnológica recompensó a quienes fueron capaces de adoptar herramientas más rápido y desarrollar experiencia más profunda.\n\nLa Inteligencia Artificial está rompiendo ese modelo.\n\nPor primera vez, la tecnología más importante no es una plataforma específica ni una habilidad técnica concreta. Es una capacidad transversal que redefine cómo aprendemos, cómo resolvemos problemas, cómo escribimos software, cómo operamos sistemas y cómo tomamos decisiones.\n\nLa pregunta ya no es qué herramienta aprender después.\n\nLa pregunta es cómo construir una estrategia personal y profesional para trabajar junto a la IA de manera efectiva.\n\nEn esta keynote exploraremos por qué muchos de los patrones de aprendizaje que funcionaron durante décadas comienzan a mostrar sus límites, qué habilidades están ganando relevancia en un mundo donde el conocimiento es cada vez más accesible y cómo los profesionales de tecnología pueden evolucionar desde especialistas en herramientas hacia arquitectos de capacidades aumentadas por IA.\n\nPorque el futuro no pertenece a quienes conozcan más tecnologías.\n\nPertenece a quienes aprendan más rápido, se adapten mejor y sepan utilizar la Inteligencia Artificial para multiplicar su impacto.", topics: ["Inteligencia Artificial", "Aprendizaje Continuo", "Evolución Profesional"] },
  { day: "day-2", time: "16:00", title: "Cierre del Evento 🎉 + Sorteos 🎁 + Foto Oficial 📸", speakerIds: ["caio-mede", "karen-quijada", "sergio-canales", "jorge-valenzuela", "caco"], type: "ignite", room: "main", description: "¡Llegamos al final de una increíble misión!\n\nAcompáñanos en el cierre oficial de DevOpsDays Santiago 2026, donde celebraremos todo lo vivido durante estos dos días de aprendizaje, colaboración y comunidad. Será el momento de agradecer a nuestros asistentes, speakers, patrocinadores, comunidades, voluntarios y a todas las personas que hicieron posible esta nueva edición.\n\nAntes de despedirnos, realizaremos el esperado sorteo de premios gracias al apoyo de nuestros patrocinadores, así que no te vayas antes de tiempo... ¡podrías llevarte una gran sorpresa!\n\nY, como ya es tradición, te invitamos a ser parte de la foto oficial del evento, un recuerdo que inmortaliza a la comunidad DevOps reunida una vez más para compartir conocimiento, crear nuevas conexiones y seguir impulsando la innovación en Chile y Latinoamérica.\n\n¡Gracias por ser parte de DevOpsDays Santiago 2026! Esperamos verte nuevamente en nuestra próxima misión. 🚀" },
];

